import time
from datetime import datetime, timedelta

from hbstock.market.feed import build_feed


def market_day(now, start_hour):
    """Market day (판매자센터 집계일) that a timestamp falls in: start_hour to the next day's start_hour."""
    return (datetime.fromtimestamp(now) - timedelta(hours=start_hour)).date()


class SyncService:
    def __init__(self, repo, client, settings, on_synced=None, now=None):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.on_synced = on_synced
        self.now = now or time.time
        self.last_sent = {}
        # sku -> market day of its last back-on-sale push (재입고 알림 반복 경고 기준: 하루 한 번)
        self.resumed_on = {}

    def run(self, full=False):
        day = market_day(self.now(), self.settings.market_day_start_hour)
        skus = [p.sku for p in self.repo.products()] if full else self.repo.take_dirty()
        if full:
            self.repo.take_dirty()
        products = [self.repo.product(sku) for sku in skus]
        lines, sent = build_feed(products, self.settings)
        # nothing to tell the market about a product whose announced quantity did not move
        changed = [
            line for line, sku in zip(lines, sent)
            if (full or self.last_sent.get(sku) != sent[sku]) and not self._resume_blocked(sku, sent, day)
        ]
        if not changed:
            return {"transfer": None, "lines": 0, "skus": []}
        transfer = self.client.push(changed)
        pushed = [line.split("\t", 1)[0] for line in changed]
        for sku in pushed:
            if self._is_resume(sku, sent):
                self.resumed_on[sku] = day
            self.last_sent[sku] = sent[sku]
        if self.on_synced:
            self.on_synced()
        return {"transfer": transfer.transfer_id, "lines": transfer.lines, "skus": pushed}

    def _is_resume(self, sku, sent):
        """Product goes from not on sale (0) back to on sale."""
        return self.last_sent.get(sku) == 0 and sent[sku] > 0

    def _resume_blocked(self, sku, sent, day):
        # a second back-on-sale in the same market day makes the market send a restock alert
        # again; hold it until the next day's 06:00 full sync (sold-out pushes are never held)
        return self._is_resume(sku, sent) and self.resumed_on.get(sku) == day

